function getNodeData(nodeName) {
  try {
    return $(nodeName).all().map(i => i.json);
  } catch (e) {
    return [];
  }
}

const staticData = $getWorkflowStaticData('global');
const seen = new Set(Array.isArray(staticData.seenPaperIds) ? staticData.seenPaperIds : []);

function clean(val) {
  if (val == null) return '';
  if (typeof val === 'string') return val;
  if (typeof val === 'object') return val._ || val['#text'] || val.text || '';
  return String(val).trim();
}

let hfPapers = [];
let naturePapers = [];
let arxivPapers = [];

// ۱. استخراج مقالات Hugging Face
const hfItems = getNodeData('Fetch HuggingFace1');
for (const item of hfItems) {
  const p = item.paper || item;
  const title = clean(p.title);
  const summary = clean(p.summary || p.abstract);
  const paperId = clean(p.id || item.id);
  const url = paperId ? `https://huggingface.co/papers/${paperId}` : '';

  if (title && url && !seen.has(url)) {
    hfPapers.push({ source: 'Hugging Face', title, summary, url });
  }
}

// ۲. استخراج مقالات Nature
const natureItems = getNodeData('XML to JSON Nature1');
for (const item of natureItems) {
  const rdf = item['rdf:RDF'] || item;
  const rawList = rdf.item || (rdf.channel && rdf.channel.item) || [];
  const entries = Array.isArray(rawList) ? rawList : [rawList];

  for (const entry of entries) {
    const title = clean(entry.title);
    const summary = clean(entry.description);
    const url = clean(entry.link || entry['rdf:about']);

    if (title && url && !seen.has(url)) {
      naturePapers.push({ source: 'Nature', title, summary, url });
    }
  }
}

// ۳. استخراج مقالات arXiv
const arxivItems = getNodeData('XML to JSON arXiv1');
for (const item of arxivItems) {
  const raw = item.feed?.entry;
  const entries = Array.isArray(raw) ? raw : (raw ? [raw] : []);
  for (const entry of entries) {
    const title = clean(entry.title);
    const summary = clean(entry.summary);
    const url = clean(entry.id);

    if (title && url && !seen.has(url)) {
      arxivPapers.push({ source: 'arXiv', title, summary, url });
    }
  }
}

// انتخاب حداقل ۱ مقاله از هر منبع برای حفظ تنوع
let selected = [];
if (hfPapers.length > 0) selected.push(hfPapers[0]);
if (naturePapers.length > 0) selected.push(naturePapers[0]);
if (arxivPapers.length > 0) selected.push(arxivPapers[0]);

// تکمیل ظرفیت ۳ مقاله اگر مقاله‌ای باقی مانده بود
const remaining = [...hfPapers.slice(1), ...naturePapers.slice(1), ...arxivPapers.slice(1)];
while (selected.length < 3 && remaining.length > 0) {
  selected.push(remaining.shift());
}

if (!selected.length) {
  return [{ json: { papers: [], ids: [], prompt: "No new papers found." } }];
}

// پرامپت با رعایت دقیق بولد بودن عنوان مقاله و تمام سرفصل‌ها
const prompt = `You are a research digest generator. Summarize each paper below in English using ONLY the provided text.

STRICT FORMAT REQUIREMENT FOR EACH PAPER:
📌 **[Paper Title]** *(Source: [Source Name])* 
- **Problem & Goal:** [1 concise sentence]
- **Key Method / Innovation:** [1 concise sentence]
- **Main Finding / Result:** [1 concise sentence]

Papers to summarize:
${selected.map((p, i) => `---
Source Name: ${p.source}
Title: ${p.title}
Abstract: ${p.summary}`).join('\n\n')}`;

return [{ json: { papers: selected, ids: selected.map(p => p.url), prompt } }];

