const inputData=$input.first()?.json||{};
let rawContent=inputData.output||inputData.text||inputData.choices?.[0]?.message?.content||'';
if(typeof rawContent!=='string') rawContent=JSON.stringify(rawContent);
if(!rawContent.trim()) throw new Error('AI summary output is empty');
function esc(s){return String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
let content=esc(rawContent.trim()).replace(/\*\*(.*?)\*\*/g,'<b>$1</b>');
if(content.length>2600) content=content.slice(0,2600)+'…';
const metadata=$('Prepare Digest1').first().json;
const papers=metadata.papers||[], ids=metadata.ids||[];
const date=new Date().toISOString().slice(0,10);
let text=`<b>Daily AI Research Digest</b> · ${date}\n\n${content}\n\n<b>Paper links:</b>\n`;
for(const p of papers){
 const url=String(p.url||'').trim();
 if(!/^https?:\/\//i.test(url)) continue;
 const line=`• <a href="${esc(url)}">${esc(p.title||p.source||'Paper')}</a> — ${esc(p.source)}\n`;
 if((text+line).length>3900) break;
 text+=line;
}
return [{json:{text,ids}}];

const ids=$('Format Telegram1').first().json.ids||[];
