const current=Array.isArray(store.seenPaperIds)?store.seenPaperIds:[];
store.seenPaperIds=[...new Set([...current,...ids])].slice(-2000);
return [{json:{marked:ids.length,totalRemembered:store.seenPaperIds.length}}];
